import React from 'react';

const TABS = [
  { id: 'home',      label: 'Home',   num: '01' },
  { id: 'checkin',   label: 'Day',    num: '02' },
  { id: 'history',   label: 'Log',    num: '03' },
  { id: 'breathing', label: 'Breathe',num: '04' },
];

export default function Nav({ page, setPage }) {
  return (
    <div style={{
      position: 'fixed',
      right: 0, top: 0, bottom: 0,
      width: 64,
      zIndex: 300,
      pointerEvents: 'none',
    }}>
      {/* Arc SVG */}
      <svg
        style={{ position: 'absolute', inset: 0, width: '100%', height: '100%', pointerEvents: 'none' }}
        viewBox="0 0 64 812"
        preserveAspectRatio="none"
      >
        <path
          d="M64 0 Q16 203 16 406 Q16 609 64 812"
          fill="none"
          stroke="rgba(26,42,42,0.07)"
          strokeWidth="1.5"
        />
      </svg>

      {/* Station hit zones */}
      <div style={{ position: 'absolute', inset: 0, display: 'flex', flexDirection: 'column', pointerEvents: 'all' }}>
        {TABS.map((tab) => {
          const active = page === tab.id;
          return (
            <button
              key={tab.id}
              onClick={() => setPage(tab.id)}
              aria-label={tab.label}
              style={{
                flex: 1,
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'flex-end',
                paddingRight: 14,
                background: 'none',
                border: 'none',
                cursor: 'pointer',
                position: 'relative',
                WebkitTapHighlightColor: 'transparent',
              }}
            >
              {/* Floating label left of arc */}
              <span style={{
                position: 'absolute',
                right: 68,
                top: '50%',
                transform: 'translateY(-50%)',
                fontSize: 10,
                fontWeight: 700,
                letterSpacing: '0.1em',
                textTransform: 'uppercase',
                color: active ? 'rgba(26,42,42,0.4)' : 'transparent',
                whiteSpace: 'nowrap',
                pointerEvents: 'none',
                transition: 'color 0.3s',
                fontFamily: "'Inter', sans-serif",
              }}>
                {tab.label}
              </span>

              {/* Dot on arc */}
              <span style={{
                position: 'absolute',
                left: 10,
                top: '50%',
                transform: 'translateY(-50%)',
                width: active ? 9 : 7,
                height: active ? 9 : 7,
                borderRadius: '50%',
                background: active ? '#2D6B6B' : 'rgba(26,42,42,0.12)',
                boxShadow: active ? '0 0 8px rgba(45,107,107,0.5)' : 'none',
                transition: 'all 0.4s cubic-bezier(0.34,1.5,0.64,1)',
                pointerEvents: 'none',
              }} />

              {/* Number */}
              <span style={{
                fontSize: active ? 34 : 26,
                fontWeight: 700,
                letterSpacing: '-0.05em',
                color: active ? 'rgba(26,42,42,0.16)' : 'rgba(26,42,42,0.07)',
                lineHeight: 1,
                transition: 'all 0.4s cubic-bezier(0.34,1,0.64,1)',
                userSelect: 'none',
                pointerEvents: 'none',
                fontFamily: "'Inter', sans-serif",
              }}>
                {tab.num}
              </span>
            </button>
          );
        })}
      </div>
    </div>
  );
}
